import assert from 'node:assert/strict';
import {writeFile,mkdir} from 'node:fs/promises';
import {join} from 'node:path';
import {chromium} from 'playwright-core';
import {here,browserPath,serve} from './runtime.mjs';
await mkdir(join(here,'runtime-touch'),{recursive:true});const host=await serve(here),browser=await chromium.launch({executablePath:browserPath,headless:true});
try{const context=await browser.newContext({viewport:{width:375,height:812},hasTouch:true,isMobile:true}),page=await context.newPage();await page.addInitScript(()=>{window.touchEvents=0;addEventListener('touchstart',()=>window.touchEvents++,{passive:true});});await page.goto(host.url+'/runtime/index.html');await page.waitForFunction(()=>document.querySelector('video').currentTime>.1);await page.locator('[data-pause]').tap();assert.equal(await page.locator('video').evaluate(v=>v.paused&&v.hidden),true);await page.locator('[data-pause]').tap();await page.waitForFunction(()=>!document.querySelector('video').paused);await page.locator('#primary').tap();assert.equal(new URL(page.url()).hash,'#work');assert.ok(await page.evaluate(()=>touchEvents)>=3);await page.screenshot({path:join(here,'runtime-touch/actions.png')});await page.evaluate(()=>{cleanupMotion();cleanupMedia();});await writeFile(join(here,'runtime-touch/evidence.json'),JSON.stringify({browser:browser.version(),viewport:{width:375,height:812},coverage:'Chromium touch/mobile emulation; no physical device tested',touchEvents:await page.evaluate(()=>touchEvents),pauseResumeAndPrimaryPassed:true},null,2)+'\n');console.log('MS_FE_TOUCH_OK');}finally{await browser.close();await host.close();}
